+base::ObjectType NCutSegmentation::Label2Type(const std::string& label) {
+  if (label == "unknown") {
+    return base::ObjectType::UNKNOWN;
+  }
+  if (label == "nonMot") {
+    return base::ObjectType::BICYCLE;
+  }
+  if (label == "pedestrian") {
+    return base::ObjectType::PEDESTRIAN;
+  }
+  if (label == "smallMot") {
+    return base::ObjectType::VEHICLE;
+  }
+  return base::ObjectType::UNKNOWN;
+}
