+        bool found = false;
+        SingleIndex match;
+        for (const auto& row : index.indexes()) {
+          if (row.position() == pos) {
+            match = row;
+            found = true;
+            break;
+          }
+        }
+        ASSERT_TRUE(found);
+        EXPECT_EQ(match.position(), pos);
+        EXPECT_EQ(match.type(), section.type);
+      }
+    }
+  }
