+        ch.throttle_status__510().battery_bms_err()) {
+      return true;
+    }
+  }
+  // brake error
+  if (ch.has_brake_status__511()) {
+    if (Brake_status__511::BRAKE_ERR_BRAKE_SYSTEM_ERR ==
+        ch.brake_status__511().brake_err()) {
+      return true;
+    }
+  }
+  return false;
+}
 
