+  reader.Init();
+  reader.Init();
+  reader.SetHistoryDepth(10);
+  EXPECT_TRUE(reader.GetHistoryDepth() == 10);
+  reader.Observe();
+  reader.Begin();
+  reader.End();
+  EXPECT_TRUE(reader.HasReceived());
+  block_mgr->GetOrCreateBlocker<UnitTest>(BlockerAttr("ch1"));
+  reader.Observe();
+  EXPECT_FALSE(reader.Empty());
