+             "failed, dt: "
+          << dt;
+    reference_model_enabled_ = false;
+  } else {
+    if (model_order_ == 1) {
+      matrix_a_reference_(0, 0) = -1.0 / tau_reference_;
+      matrix_b_reference_(0, 0) = 1.0 / tau_reference_;
+    } else if (model_order_ == 2) {
