+      matrix_b_reference_(1, 0) = wn_reference_ * wn_reference_;
+    } else {
+      AWARN << "reference model order beyond the designed range, "
+               "model_order: "
+            << model_order_;
+      reference_model_enabled_ = false;
+    }
+  }
+  reference_model_enabled_ = true;
