+    const std::string warn =
+        absl::StrCat(process_dag_path, " has high memory usage: ", memory_usage,
+                     " > ", high_memory_warning);
+    SummaryMonitor::EscalateStatus(ComponentStatus::WARN, warn, status);
+  }
 }
 
