-
-    return v->size();
-  }
-
-  size_t size() const {
-    boost::mutex::scoped_lock lock(mutex_);
-    return queue_.size();
-  }
-
- private:
-  mutable boost::mutex mutex_;
-  boost::condition_variable not_empty_;
-  std::deque<T> queue_;
-  uint size_ = 0;
-  std::string name_;
-};
